def transform(grid):
    g = np.array(grid)
    h, w = g.shape
    bg = background(g)
    H = 10

    def shift(row, dx):
        r = np.full(w, bg, dtype=g.dtype)
        for x in range(w):
            nx = x + dx
            if 0 <= nx < w:
                r[nx] = row[x]
        return r

    best = None
    for dy in range(1, h):
        for dx in sorted(range(-w + 1, w), key=lambda d: (abs(d), d)):
            if all(np.array_equal(shift(g[y - dy], dx), g[y]) for y in range(dy, h)):
                best = (dy, dx)
                break
        if best:
            break
    if best is None:
        best = (h, 0)
    dy, dx = best

    out = np.full((max(H, h), w), bg, dtype=g.dtype)
    out[:h] = g
    emit(out, f"Allocate a {out.shape[0]}x{w} canvas and copy the input into the top {h} rows. "
              f"The input repeats every {dy} row(s) with a horizontal shift of {dx}.")
    for y in range(h, out.shape[0]):
        out[y] = shift(out[y - dy], dx)
    emit(out, f"Extend the pattern downward: each new row is the row {dy} above shifted by {dx}, "
              f"dropping cells that leave the grid.")
    return out
